package com.wyj.kgc; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; public class BcryptTest { public static void main(String[] args) { BCryptPasswordEncoder encoder = new BCryptPasswordEncoder(); String hash = "$2a$10$ONi64FybB2amlwWuEhzJpurwBpjSF/FNSYSfPVyvblQin/uVfCXpa"; String[] common = {"123456", "12345678", "admin", "password", "111111"}; for (String p : common) { if (encoder.matches(p, hash)) { System.out.println("MATCH FOUND: " + p); return; } } System.out.println("NO MATCH"); System.out.println("Hash for 123456: " + encoder.encode("123456")); } }